import{_ as s,o as t,c as n,ag as i}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-10-27（物理 / 纳米光子学 / 光学角动量 OAM）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/science-daily-2026-10-27-physics.md","filePath":"topics/physics/science-daily-2026-10-27-physics.md"}'),r={name:"topics/physics/science-daily-2026-10-27-physics.md"};function e(c,o,a,l,g,d){return t(),n("div",null,[...o[0]||(o[0]=[i('<h1 id="科学日报-·-2026-10-27-物理-纳米光子学-光学角动量-oam" tabindex="-1">科学日报 · 2026-10-27（物理 / 纳米光子学 / 光学角动量 OAM） <a class="header-anchor" href="#科学日报-·-2026-10-27-物理-纳米光子学-光学角动量-oam" aria-label="Permalink to &quot;科学日报 · 2026-10-27（物理 / 纳米光子学 / 光学角动量 OAM）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-27.md</code> — 第46期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-physics</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-27-把「光学涡旋」做成腔而不是透镜-尺寸压到-λ-10-以下" tabindex="-1">科学日报 2026-10-27：把「光学涡旋」做成腔而不是透镜，尺寸压到 λ/10 以下 <a class="header-anchor" href="#科学日报-2026-10-27-把「光学涡旋」做成腔而不是透镜-尺寸压到-λ-10-以下" aria-label="Permalink to &quot;科学日报 2026-10-27：把「光学涡旋」做成腔而不是透镜，尺寸压到 λ/10 以下&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-27.md</code> ｜ DOI: 10.1038/s41467-026-78518-5 ｜ Nature Communications (2026)</p></blockquote><ul><li>问题：<strong>光轨道角动量（OAM）</strong> 的紧凑调控是<strong>芯片级光子集成</strong>的核心。此前的 <strong>等离子体涡旋透镜（plasmonic vortex lens）</strong> 是片上 OAM 编码/操控的主要平台（靠可调拓扑荷工程），但<strong>光斑尺寸</strong>限制了其在<strong>纳米尺度</strong>的集成与和物质的相互作用。</li><li>本工作：提出 <strong>「等离子体涡旋腔」（plasmonic vortex cavities）</strong> —— 一种基于 <strong>间隙等离激元（gap-plasmon）</strong> 的<strong>腔型</strong>涡旋约束概念：等离子体涡旋由一个 <strong>金属—绝缘体—金属（MIM）腔</strong>支撑，<strong>占位面积 &lt; λ/10、环形特征 &lt; λ/60</strong>。</li><li>机制（统一物理框架）： <ul><li><strong>间隙宽度控制</strong>强平坦化的 <strong>gap-SPP 色散</strong> → <strong>压缩 SPP 波长</strong> → 把涡旋尺寸推向由<strong>量子效应</strong>设定的<strong>超紧凑极限</strong>；</li><li>腔的<strong>本征反射</strong> → 强<strong>驻波增强</strong>。</li><li><strong>全波模拟</strong>与框架一致，在深亚波长占位内给出<strong>清晰而强的涡旋场（PV fields）</strong>。</li></ul></li><li>意义：这是从 <strong>「透镜型」到「腔型」涡旋的范式转变</strong> —— 提供<strong>超紧凑的 OAM 平台</strong>，推进芯片级集成。</li><li>洞察（对本库 <code>physics</code> × <code>ai-brain</code>）： <ol><li><strong>「把器件从一种工作原理换成另一种」往往比「把原原理优化到极限」更能突破尺寸墙</strong> —— 透镜型涡旋的尺寸由<strong>衍射/聚焦</strong>定；腔型涡旋改用<strong>色散压缩 + 驻波</strong>来定尺寸，于是极限从「光学」挪到<strong>量子效应</strong>。这与本库反复出现的**「极限是工具的属性、不是自然的属性」**（见 <code>topics/physics/index.md</code> 开篇命题）<strong>同构</strong>：<strong>当你在一条曲线上优化到撞墙时，先问能不能换一条曲线。</strong></li><li><strong>「深亚波长 + 强场」这对通常互斥的目标，靠『腔内驻波』同时满足</strong> —— 与 10-24「声子 κ_aa/κ_ab 同温出峰」、10-26「亚周期激光把能量×周期数×CEP 同时推到位」同族：<strong>当两个目标被同一条通道绑成权衡（越小越弱）时，引入一个『本征共振』通道把它们解耦，而不是在旧通道里折中。</strong> 可写入本库元判据：<strong>「缩小 → 增强」的悖论，常由『腔/共振』解开。</strong></li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/physics/index.md</code> ｜ 第46期 科学板块</p></blockquote><p>关键词：科学日报第46期、等离子体涡旋腔 plasmonic vortex cavity、光学角动量 OAM、芯片级光子集成、间隙等离激元 gap-plasmon、MIM 金属-绝缘体-金属腔、占位小于 λ/10、环形特征小于 λ/60、gap-SPP 色散压缩波长、量子极限、本征反射驻波增强、深亚波长强场、透镜型到腔型范式转变、极限是工具属性、换曲线不撞墙、腔/共振解权衡</p><p>关联：<code>topics/physics/science-daily-2026-10-26-physics.md</code>（亚周期中红外激光 / 高压冰）、<code>topics/physics/index.md</code>、<code>topics/materials/index.md</code>、<code>topics/ai-brain/index.md</code></p>',10)])])}const h=s(r,[["render",e]]);export{m as __pageData,h as default};
